using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using UnityEngine;
using UnityEngine.Rendering;

[DefaultExecutionOrder(-60)] public sealed class SurfaceScatter:MonoBehaviour {
 [StructLayout(LayoutKind.Sequential)]struct Rock{public double x,y,z,radius;}
 [DllImport("blackhole",CallingConvention=CallingConvention.Cdecl)]static extern int bh_set_rocks([In]Rock[] rocks,int count);
 public static SurfaceScatter Current;PlanetExpedition expedition;PlanetExpedition.Planet planet;Camera view;Mesh mesh,combinedMesh;GameObject field;Material material;readonly List<Vector3> positions=new List<Vector3>();readonly List<float> radii=new List<float>();Rock[] native=new Rock[192];Matrix4x4[] matrices=new Matrix4x4[192];string cell="";
 public int Count{get{return positions.Count;}}public PlanetExpedition.Planet BoundPlanet{get{return planet!=null&&planet.root!=null&&field!=null&&field.transform.parent==planet.root.transform?planet:null;}}public int RenderedVertices{get{return combinedMesh!=null?combinedMesh.vertexCount:0;}}
 public void Initialize(PlanetExpedition owner){Current=this;expedition=owner;view=Camera.main;var g=new SurfaceArt.Geometry();g.Ellipsoid(Vector3.zero,Vector3.one,Color.white,40,26);mesh=g.Mesh("Eroded boulder / smooth sculpted normals");
 var verts=mesh.vertices;for(int i=0;i<verts.Length;i++){Vector3 d=verts[i].normalized;float broad=Mathf.Sin(d.x*4.2f+d.y*2.7f)*Mathf.Cos(d.z*4.7f-d.y*1.8f),fine=Mathf.Sin(d.x*15+d.y*9)*Mathf.Cos(d.z*13+d.y*7);verts[i]=d*(.90f+.11f*broad+.025f*fine);}
 mesh.vertices=verts;mesh.RecalculateNormals();WeldNormals(mesh);mesh.RecalculateBounds();material=RockMaterial();}
 static void WeldNormals(Mesh mesh){var v=mesh.vertices;var n=mesh.normals;var sums=new Dictionary<Vector3Int,Vector3>();for(int i=0;i<v.Length;i++){var key=Vector3Int.RoundToInt(v[i]*10000);if(sums.TryGetValue(key,out var sum))sums[key]=sum+n[i];else sums[key]=n[i];}for(int i=0;i<v.Length;i++)n[i]=sums[Vector3Int.RoundToInt(v[i]*10000)].normalized;mesh.normals=n;}
 public void Refresh(){cell="";var scenery=GetComponent<SurfaceScenery>();if(scenery!=null)scenery.Refresh();var flora=GetComponent<SurfaceFlora>();if(flora!=null)flora.Refresh();}
 public float Altitude(Vector3 p,float alt){if(BoundPlanet==null||alt>15)return alt;Vector3 local=p-planet.body.P;for(int i=0;i<positions.Count;i++){Vector3 d=local-positions[i];if(d.sqrMagnitude<100)alt=Mathf.Min(alt,d.magnitude-radii[i]*.94f);}if(SurfaceScenery.Current!=null)alt=SurfaceScenery.Current.Altitude(planet,p,alt);return SurfaceSettlement.Current!=null?SurfaceSettlement.Current.Altitude(planet,p,alt):alt;}
 public Vector3 Clearance(Vector3 p,float clearance){if(BoundPlanet==null)return p;for(int i=0;i<positions.Count;i++){Vector3 c=planet.body.P+positions[i],d=p-c;float r=radii[i]+clearance;if(d.sqrMagnitude<r*r&&d.sqrMagnitude>.001f)p=c+d.normalized*r;}if(SurfaceScenery.Current!=null)p=SurfaceScenery.Current.Clearance(planet,p,clearance);return SurfaceSettlement.Current!=null?SurfaceSettlement.Current.Clearance(planet,p,clearance):p;}
 void Rebuild(Vector3 dir){positions.Clear();radii.Clear();Vector3[] normals={Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};for(int face=0;face<6;face++){Vector3 n=normals[face];float facing=Vector3.Dot(dir,n);if(facing<.55f)continue;Vector3 a=new Vector3(n.y,n.z,n.x),b=Vector3.Cross(n,a),cube=dir/facing;float tile=30/(float)planet.body.radius;int cx=Mathf.FloorToInt((Vector3.Dot(cube,a)+1)/tile),cy=Mathf.FloorToInt((Vector3.Dot(cube,b)+1)/tile);
  for(int x=cx-3;x<=cx+3;x++)for(int y=cy-3;y<=cy+3;y++){int seed=unchecked(x*73856093^y*19349663^face*83492791^(int)(planet.body.seed%1000)*1107);var rng=new System.Random(seed);if(rng.NextDouble()<.3)continue;float u=(x+(float)rng.NextDouble())*tile-1,v=(y+(float)rng.NextDouble())*tile-1;if(Mathf.Abs(u)>1||Mathf.Abs(v)>1)continue;Vector3 d=PlanetTerrainLOD.Direction(face,u,v);float h=PlanetExpedition.Height(d,planet.body.seed,planet.body.radius);if(h<1||expedition.Alt(planet.body.P+d*((float)planet.body.radius+h))<-.25f)continue;float r=.8f+(float)rng.NextDouble()*3.6f;var operations=expedition.GetComponent<SurfaceOperations>();if(operations!=null&&operations.ReservedApproach(planet,d*((float)planet.body.radius+h),r))continue;positions.Add(d*((float)planet.body.radius+h+r*.35f));radii.Add(r);if(positions.Count>=105){BuildVisible();return;}}}BuildVisible();
 }
 Material RockMaterial(){var m=new Material(Shader.Find("Orbit/PlanetRock"));m.SetTexture("_BaseMap",Resources.Load<Texture2D>("Surfaces/rock_diff"));m.SetTexture("_BumpMap",Resources.Load<Texture2D>("Surfaces/rock_normal"));return m;}
 void BuildVisible(){if(field==null){field=new GameObject("Deterministic local boulder field");field.AddComponent<MeshFilter>();field.AddComponent<MeshRenderer>();}field.transform.SetParent(planet.root.transform,false);field.transform.localPosition=Vector3.zero;field.transform.localRotation=Quaternion.identity;field.transform.localScale=Vector3.one;if(material==null)material=RockMaterial();material.SetFloat("_Climate",(int)SurfaceEcology.Climate(planet.key));if(combinedMesh!=null)Destroy(combinedMesh);combinedMesh=new Mesh{name="Boulder geometry / matching local native field",indexFormat=IndexFormat.UInt32};var pieces=new CombineInstance[positions.Count];for(int i=0;i<pieces.Length;i++)pieces[i]=new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(positions[i],Quaternion.Euler(0,i*137,0),Vector3.one*radii[i])};if(pieces.Length>0)combinedMesh.CombineMeshes(pieces,true,true);combinedMesh.RecalculateBounds();field.GetComponent<MeshFilter>().sharedMesh=combinedMesh;field.GetComponent<Renderer>().sharedMaterial=material;field.SetActive(pieces.Length>0);}
 void Update(){if(expedition==null)return;Vector3 p=view.transform.position;var nearest=expedition.Nearest(p);if(nearest==null||expedition.Alt(p)>200){positions.Clear();if(field!=null)field.SetActive(false);planet=null;cell="";bh_set_rocks(native,0);return;}Vector3 dir=(p-nearest.body.P).normalized;string next=nearest.key+"/"+Mathf.FloorToInt(dir.x*(float)nearest.body.radius/15)+"/"+Mathf.FloorToInt(dir.y*(float)nearest.body.radius/15)+"/"+Mathf.FloorToInt(dir.z*(float)nearest.body.radius/15);if(next!=cell||nearest!=planet||field==null){planet=nearest;cell=next;Rebuild(dir);}for(int i=0;i<positions.Count;i++){Vector3 c=planet.body.P+positions[i];native[i]=new Rock{x=c.x,y=c.y,z=c.z,radius=radii[i]*.94};matrices[i]=Matrix4x4.TRS(c,Quaternion.Euler(0,i*137,0),Vector3.one*radii[i]);}int count=positions.Count;var settlement=SurfaceSettlement.Current;if(settlement!=null&&settlement.BoundPlanet==planet)for(int i=0;i<settlement.Contacts.Count&&count<native.Length;i++){Vector3 c=planet.body.P+settlement.Contacts[i];native[count++]=new Rock{x=c.x,y=c.y,z=c.z,radius=settlement.Radii[i]};}var scenery=SurfaceScenery.Current;
 if(scenery!=null&&scenery.BoundPlanet==planet)for(int i=0;i<scenery.Contacts.Count&&count<native.Length;i++){Vector3 c=planet.body.P+scenery.Contacts[i];native[count++]=new Rock{x=c.x,y=c.y,z=c.z,radius=scenery.Radii[i]};}
 bh_set_rocks(native,count);}
 void OnDestroy(){bh_set_rocks(native,0);if(mesh!=null)Destroy(mesh);if(combinedMesh!=null)Destroy(combinedMesh);if(field!=null)Destroy(field);if(material!=null)Destroy(material);if(Current==this)Current=null;}
}
